const results = await Promise.allSettled([
  tools.exec_command({cmd:"git status --short","max_output_tokens":4000}),
  tools.exec_command({cmd:"cat docs/decisions/2026-10-08-task-context-handoff.md","max_output_tokens":5000}),
  tools.exec_command({cmd:"rg --files -g 'AGENTS.md' -g '!hermes/**' -g '!node_modules/**' -g '!runtime/vault/**'","max_output_tokens":1000}),
  tools.exec_command({cmd:"rg -n 'memory|session_search|session_key|thread_ts|per_user|user_id|history' runtime config scripts --glob '*.py' --glob '*.yaml' --glob '*.md' --glob '*.sh'","max_output_tokens":7000})
]); results.forEach((r,i)=>text({i,...(r.status==="fulfilled"?r.value:{error:String(r.reason)})}));

