  tools.exec_command({cmd:"cat hermes/AGENTS.md hermes/gateway/AGENTS.md","max_output_tokens":7500}),
  tools.exec_command({cmd:"rg -n 'memory|session_search|HERMES_HOME|profile|gateway|channel|thread' README.md docs/SETUP.md scripts --glob '!*.json'","max_output_tokens":6500}),
  tools.exec_command({cmd:"sed -n '1,240p' hermes/gateway/session_identity.py","max_output_tokens":6000}),
