text((await tools.exec_command({cmd:".local/hermes-lab/venv/bin/python - <<'PY'
from pathlib import Path
import json, sqlite3
home=Path('.local/hermes-lab/home')
for p in [home,*[home/'profiles'/x for x in ('slack-t0c6j1xcde0-c0c6j277zng','slack-t0c6j1xcde0-c0c6e6umxbl')]]:
    db=sqlite3.connect(f'file:{p}/state.db?mode=ro',uri=True);db.row_factory=sqlite3.Row
    rows=db.execute("SELECT m.session_id,m.role,m.content,s.thread_id,s.chat_id,s.user_id,s.tool_names FROM messages m JOIN sessions s ON s.id=m.session_id WHERE m.role='user' AND (lower(m.content) LIKE '%fly to on 9th%' OR lower(m.content) LIKE '%one way flight to mumbai%' OR lower(m.content) LIKE '%one-way flight to mumbai%') ORDER BY m.timestamp DESC LIMIT 8").fetchall()
    for row in rows:
        print('profile',p.name,'match',json.dumps(dict(row)))
        if 'fly to on 9th' in row['content'].lower():
            for msg in db.execute('SELECT role,content,tool_name,tool_calls FROM messages WHERE session_id=? ORDER BY id',(row['session_id'],)):
                v=dict(msg)
                for k in ('content','tool_calls'):
                    if v[k] and len(v[k])>2300:v[k]=v[k][:2300]+' [truncated]'
                print('recall turn',json.dumps(v))
    db.close()
PY","max_output_tokens":5500})).output);

