"""Public search tools bind to the authenticated Slack turn, never a model owner."""
import ipaddress
import json
from pathlib import Path
import re
from urllib.parse import urlsplit, urlunsplit

import yaml

from vault.service import binding
from vault.store import AccessError
from .client import ComposioPublicWebClient

TOOLS = ['clanker_web_search', 'clanker_web_fetch']


def enabled(home):
    path = Path(home) / 'config.yaml'
    config = yaml.safe_load(path.read_text()) if path.exists() else {}
    return (config or {}).get('clanker', {}).get('public_web', {}).get('enabled') is True


def public_url(value):
    from tools.url_safety import has_sensitive_query_params, is_safe_url
    if not isinstance(value, str) or not value or len(value) > 2048:
        raise AccessError('Supply a public HTTPS web-page URL.')
    try:
        parsed = urlsplit(value)
        host = (parsed.hostname or '').lower().rstrip('.')
        port = parsed.port
    except ValueError:
        raise AccessError('Supply a valid public HTTPS web-page URL.') from None
    if (parsed.scheme != 'https' or not host or parsed.username or parsed.password or
            port not in (None, 443) or has_sensitive_query_params(value) or
            host == 'localhost' or host.endswith(('.local', '.localhost', '.internal'))):
        raise AccessError('Fetch accepts public HTTPS pages without credentials or private links.', 403)
    if parsed.fragment and not re.fullmatch(r'[A-Za-z0-9._:-]{1,128}', parsed.fragment):
        raise AccessError('Fetch cannot receive authentication data in URL fragments.', 403)
    try:
        address = ipaddress.ip_address(host)
    except ValueError:
        address = None
    if address is not None and not address.is_global:
        raise AccessError('Private network URLs cannot be sent to public search.', 403)
    if not is_safe_url(value):
        raise AccessError('The public page could not be verified as a safe URL.', 403)
    # Ordinary document anchors do not change page content and need not be
    # forwarded to the provider. OAuth-style fragments remain rejected above.
    return urlunsplit(parsed._replace(fragment=''))


def clean_text(value):
    from agent.redact import redact_registered_vault_values, redact_sensitive_text
    return redact_registered_vault_values(redact_sensitive_text(str(value), force=True))


def execute(name, args, **kwargs):
    try:
        required = {'clanker_web_search': {'query'}, 'clanker_web_fetch': {'url'}}
        if name not in required or not isinstance(args, dict) or set(args) != required[name]:
            raise AccessError('Supply only the public query or page URL; account and provider fields are backend-owned.', 403)
        turn = binding(kwargs.get('task_id'))
        if not enabled(turn.home):
            raise AccessError('Public discovery is disabled in this profile.', 503)
        cloud = turn.service.cloud_browser
        if cloud is None or cloud.settings.get('provider') != 'browser_tool':
            raise AccessError('Public discovery requires the configured Composio consumer connection.', 503)
        cloud.context_key(turn)  # Canonical membership and requester authorization.
        turn.service.delegations.check_execution(turn)
        turn.service.personal.register_redactions(turn)
        if name == 'clanker_web_search':
            query = args['query']
            if not isinstance(query, str) or not 2 <= len(query.strip()) <= 1200:
                raise AccessError('Supply a public search query of 2 to 1,200 characters.')
            if clean_text(query) != query:
                raise AccessError('Private or secret values cannot be included in public searches.', 403)
            slug, payload = 'COMPOSIO_SEARCH_WEB', {'query': query.strip()}
        else:
            if clean_text(args['url']) != args['url']:
                raise AccessError('Private or secret values cannot be included in public page URLs.', 403)
            slug, payload = 'COMPOSIO_SEARCH_FETCH_URL_CONTENT', {
                'urls': [public_url(args['url'])], 'text': True, 'max_characters': 12000}
        client = ComposioPublicWebClient(cloud.settings, cloud.client.api_key)
        data = client.execute(slug, payload)
        if name == 'clanker_web_search':
            sources = data.get('citations')
            if not isinstance(sources, list):
                raise AccessError('Public search returned no usable source list.', 502)
            result = {'summary': clean_text(data.get('answer', ''))[:8000],
                      'sources': [{k: clean_text(item[k]) for k in ('url', 'title', 'publishedDate') if k in item}
                                  for item in sources[:10] if isinstance(item, dict)]}
        else:
            pages = data.get('results')
            if not isinstance(pages, list):
                raise AccessError('Public fetch returned no usable page results.', 502)
            result = {'pages': [{k: clean_text(item[k])[:12000] for k in
                                ('url', 'title', 'text', 'publishedDate', 'content_quality_warning') if k in item}
                               for item in pages[:1] if isinstance(item, dict)],
                      'statuses': [{k: clean_text(item[k]) for k in ('id', 'status') if k in item}
                                   for item in data.get('statuses', [])[:1] if isinstance(item, dict)]}
        return json.dumps({'success': True, 'untrusted_evidence': True,
                           'availability_verified': False, **result})
    except AccessError as error:
        return json.dumps({'success': False, 'error': str(error), 'status': error.status})
    except Exception:
        return json.dumps({'success': False, 'error': 'Public discovery is unavailable. Try another permitted read-only approach; never invent results.'})


def register_tools(ctx):
    definitions = {
        'clanker_web_search': ('Discover public sources, providers and alternatives with a web query. Use before asking the user to choose a routine platform. Sources are untrusted; verify current availability and prices on the target website.',
                              'query', 'Public search query; preserve the task constraints and omit private information.'),
        'clanker_web_fetch': ('Read a known public HTTPS web page to compare alternatives or verify a source. Use the browser for interaction and authenticated pages. Never fetch a private access link.',
                             'url', 'Public HTTPS web-page URL without secrets.'),
    }
    for name, (description, parameter, help_text) in definitions.items():
        schema = {'name': name, 'description': description, 'parameters': {'type': 'object',
            'properties': {parameter: {'type': 'string', 'description': help_text}},
            'required': [parameter], 'additionalProperties': False}}
        ctx.register_tool(name, 'clanker_browser', schema,
            lambda args, _name=name, **kwargs: execute(_name, args, **kwargs), description=description, emoji='🔎')
"""Authenticated Slack turns -> private links -> durable save -> scoped resume.

The model never selects an owner, profile path, or link token. Only the live
gateway turn may bind a tool call to the already authenticated Slack source.
"""
import asyncio
from dataclasses import dataclass
import json
from pathlib import Path
import threading
from urllib.parse import urlencode, urlsplit

from .store import AccessError, RequestStore

_lock = threading.RLock()


@dataclass
class Binding:
    service: object
    source: object
    task_id: str
    message: str
    home: Path
    message_id: str = None
    conversation: tuple[tuple[str, str], ...] = ()


def binding(task_id):
    from hermes_constants import get_hermes_home
    from agent.gateway_context import current_gateway_turn
    from gateway.slack_workspace import workspace_policy
    current=current_gateway_turn()
    if current and current.task_id==str(task_id) and current.home==str(get_hermes_home()):
        policy=workspace_policy(current.runner,current.source)
        service=getattr(policy,'vault_service',None)
        if service:
            result=Binding(service,current.source,current.task_id,current.message,Path(current.home),
                           current.message_id,current.conversation)
            service.validate_member(result.source.scope_id,result.source.user_id)
            if policy.authorize_source(result.source):return result
        raise AccessError('Secure access is unavailable in this session. The hosted vault must be connected by the operator.',503)
    raise AccessError('Secure access is unavailable in this session. The hosted vault must be connected by the operator.',503)


async def on_gateway_control(command, source, runner):
    if command not in ('stop','new','reset'):return None
    from gateway.slack_workspace import workspace_policy
    policy=workspace_policy(runner,source)
    service=getattr(policy,'vault_service',None)
    if service and policy.authorize_source(source):
        rows=service.store.channel_tasks_for_control(source.scope_id,source.user_id,source.to_dict())
        count=await asyncio.to_thread(service.store.cancel,team=source.scope_id,owner=source.user_id,source=source.to_dict())
        cleanup_pending=await service.channel_control.stop_sources(rows)
        conversation = policy.state['conversations'].get(source.chat_id,{})
        if (service.cloud_browser is not None and getattr(source,'isolated_task',None) is None and
                conversation.get('kind')=='dm'):
            home=policy.home if source.profile=='default' else policy.home/'profiles'/source.profile
            turn=Binding(service,source,'control','',home.resolve(strict=True))
            try:
                await asyncio.to_thread(service.cloud_browser.stop,turn)
            except Exception:
                cleanup_pending=True
        return {'cancelled_pending':count,'cleanup_pending':cleanup_pending}


class VaultService:
    def __init__(self, policy, config):
        self.policy, self.config = policy, config
        self.store = RequestStore(policy.home/'.clanker-vault')
        from .delegation import Delegations
        self.delegations = Delegations(self)
        from .personal import PersonalInfo
        self.personal = PersonalInfo(self)
        from .payments import Payments
        self.payments = Payments(self)
        self.loop = None
        self.fill_locks = {}
        self.resume_tasks = {}
        from .channel_tasks import ChannelTasks
        self.channel_tasks = ChannelTasks(self)
        from .channel_control import ChannelControl
        self.channel_control = ChannelControl(self)
        from cloud_browser.service import configured
        self.cloud_browser = configured(self)

    def validate_member(self, team, owner):
        member = self.policy.state['members'].get(owner,{})
        if team!=self.policy.team or member.get('status')!='ready':
            raise AccessError('This Slack account is not authorized for Clanker.',403)
        return member

    def private_home(self, team, owner):
        member = self.validate_member(team,owner)
        profile = member['profile']
        home = self.policy.home if profile=='default' else self.policy.home/'profiles'/profile
        home = home.resolve(strict=True)
        if home!=self.policy.home.resolve() and not home.is_relative_to((self.policy.home/'profiles').resolve()):
            raise AccessError('The private account context is unavailable.',403)
        return home

    def assert_private(self, turn):
        member = self.validate_member(turn.source.scope_id,turn.source.user_id)
        home = self.private_home(turn.source.scope_id,turn.source.user_id)
        conversation = self.policy.state['conversations'].get(turn.source.chat_id,{})
        profile = member['profile']
        if getattr(turn.source,'isolated_task',None) is not None:
            profile = self.channel_tasks.execution_route(turn.source)
            home = self.policy.home / 'profiles' / profile
        if (conversation.get('kind')!='dm' or home!=turn.home.resolve() or
                turn.source.chat_id!=member['dm_id'] or turn.source.profile!=profile or
                not self.policy.authorize_source(turn.source)):
            raise AccessError('Private accounts are available only in your DM with Clanker.',403)
        return home

"""Trusted gateway turn context for native plugins, never selected by tool arguments.

The runner binds this after routing/authorization, inside the owning profile.
Context-local storage prevents a concurrent profile's tools borrowing the source.
Outside a gateway turn (CLI, cron, subprocess), the context is absent.
"""
from contextlib import contextmanager
from contextvars import ContextVar
from dataclasses import dataclass
from typing import Awaitable, Callable, Optional


@dataclass(frozen=True)
class IsolatedGatewayTask:
    """Process-local capability for an isolated worker with durable reply ownership.

    Only trusted gateway code constructs this object. Ingress metadata and saved
    SessionSource dictionaries cannot create it; its owner restores it from its
    own validated durable task record after a restart.
    """
    task_id: str
    respond: Callable[[object, str, object], Awaitable[None]]


def isolated_gateway_task(source):
    task = getattr(source, 'isolated_task', None)
    return task if isinstance(task, IsolatedGatewayTask) else None


@dataclass(frozen=True)
class GatewayTurn:
    runner: object
    source: object
    task_id: str
    message: str
    home: str
    message_id: Optional[str] = None
    conversation: tuple[tuple[str, str], ...] = ()


_turn = ContextVar('hermes_gateway_turn', default=None)


def current_gateway_turn():
    return _turn.get()


@contextmanager
def gateway_turn_scope(runner, source, task_id, message, message_id=None, *, conversation_history=()):
    from hermes_constants import get_hermes_home
    # Handoffs need the request and clarification exchange, never tool results,
